function layerMotion(term){
 const id=Number(term.id),m=motionLayers[id];if(!m)return null;
 const [si,x,y,w,h,layers]=m,[file,W,H]=motionSheets[si];
 const img=`<image href="/pictograms/${file}" x="0" y="0" width="${W}" height="${H}" style="mix-blend-mode:multiply"/>`;
 const org=(o,bx,by,bw,bh)=>{const cx=bx+bw/2,cy=by+bh/2;return o==='l'?`${bx}px ${cy}px`:o==='r'?`${bx+bw}px ${cy}px`:o==='bl'?`${bx}px ${by+bh}px`:`${cx}px ${cy}px`};
 let holes='',defs='',body='';
 layers.forEach(([a,b,c,d,anim,loop,o,p],i)=>{
  if(!p)return;
  const circ=o.c,bx=circ?a-c:a,by=circ?b-c:b,bw=circ?2*c:c,bh=circ?2*c:d,cid=`ml${id}-${i}`;
  const t=anim&&anim[0]==='t';
  holes+=`<path d="${p}" fill="#000" fill-rule="evenodd"/>`;
  defs+=`<clipPath id="${cid}"><path d="${p}" clip-rule="evenodd"/></clipPath>`;
  if(t)defs+=`<clipPath id="${cid}t"><rect x="${bx-6}" y="${by-6}" width="${bw+12}" height="${bh+12}" class="${anim}"/></clipPath>`;
  const st=`transform-box:view-box;transform-origin:${org(o.o,bx,by,bw,bh)}`;
  const inner=`<g clip-path="url(#${cid})">${img}</g>`;
  body+=`<g class="${t?'':anim}" style="${st};--dx:${o.dx||0}px;--dy:${o.dy||0}px"><g class="${loop}" style="${st};animation-delay:${o.d||0}s">${t?`<g clip-path="url(#${cid}t)">${inner}</g>`:inner}</g></g>`;
 });
 const frame=el('div','term-pictogram mp');
 frame.innerHTML=`<svg class="mp-wipe" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${term.term} 움직이는 픽토그램" preserveAspectRatio="xMidYMid meet"><defs>${defs}<mask id="mlb${id}" maskUnits="userSpaceOnUse" x="${x-10}" y="${y-10}" width="${w+20}" height="${h+20}"><rect x="${x-10}" y="${y-10}" width="${w+20}" height="${h+20}" fill="#fff"/>${holes}</mask></defs><g class="m-all"><g mask="url(#mlb${id})">${img}</g>${body}</g></svg>`;
 return frame;
}
// 나머지 분야: 원본 펜 그림을 조각별로 하나씩 나타나게 함(용어 글씨는 잘라냄)
function rasterMotion(term){
 const id=Number(term.id),m=motionRaster[id];if(!m)return null;
 const [si,x,y,w,h,parts]=m,[file,W,H]=motionSheets[si],n=parts.length;
 const img=`<image href="/pictograms/${file}" x="0" y="0" width="${W}" height="${H}" style="mix-blend-mode:multiply"/>`;
 let defs='',body='';
 parts.forEach(([px,py,pw,ph,sp],i)=>{
  const slot=n>1?Math.round(1+i*9/(n-1)):1,cid=`mr${id}-${i}`;
  defs+=`<clipPath id="${cid}"><rect x="${px}" y="${py}" width="${pw}" height="${ph}"/></clipPath>`;
  body+=`<g class="p${slot}" style="transform-box:view-box;transform-origin:${px+pw/2}px ${py+ph/2}px"><g class="${sp?'blink':''}" clip-path="url(#${cid})">${img}</g></g>`;
 });
 const frame=el('div','term-pictogram mp');
 frame.innerHTML=`<svg class="mp-wipe" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${term.term} 움직이는 픽토그램" preserveAspectRatio="xMidYMid meet"><defs>${defs}</defs><g class="m-all">${body}</g></svg>`;
 return frame;
}
function motionPictogram(term){
 const id=Number(term.id),body=motionPictograms[id];
 if(!body)return layerMotion(term)||rasterMotion(term);
 const frame=el('div','term-pictogram mp');
 frame.innerHTML=`<svg viewBox="0 0 400 250" role="img" aria-label="${term.term} 움직이는 픽토그램" preserveAspectRatio="xMidYMid meet"><g class="m-all" fill="none" stroke="#1b1b1b" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
 return frame;
}
